package com.ruoyi.web.controller.shop;
import java.util.*;import com.alibaba.fastjson2.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Lazy;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.ruoyi.web.controller.shop.ShopService.*;
@Service public class ShopDistribution {
 @Autowired @Lazy ShopService s;
 public JSONObject settings(){JSONObject c=JSON.parseObject(str(s.one("select content from shop_config where config_key='distribution'").get("content")));c.putIfAbsent("attributionDays",0);return c;}
 public java.sql.Timestamp newExpiry(){long days=settings().getLongValue("attributionDays");return days==0?null:new java.sql.Timestamp(System.currentTimeMillis()+days*86400000L);}
 private long effectiveReferrer(long uid){Map<String,Object> m=s.one("select referrer_id,referrer_expires_at from shop_member where id=?",uid);return m.get("referrer_expires_at")!=null&&timestamp(m.get("referrer_expires_at")).getTime()<=System.currentTimeMillis()?0:number(m.get("referrer_id"));}
 public List<Map<String,Object>> rules(){return s.jdbc().queryForList("select r.*,p.name product_name from shop_distribution_rule r left join shop_product p on p.id=r.product_id order by r.id");}
 private boolean valid(long uid){return uid>0&&s.jdbc().queryForObject("select count(*) from shop_member where id=? and enabled=1 and distributor_state='approved'",Long.class,uid)>0;}
 public void inherit(long company,long owner){long ref=effectiveReferrer(owner);s.jdbc().update("insert ignore into shop_company_referral(company_id,referrer_id,expires_at) values(?,?,?)",company,valid(ref)&&ref!=owner?ref:null,newExpiry());}
 @Transactional public void relation(long uid,long ref,boolean correct,String reason,String who){s.one("select config_key from shop_config where config_key='distribution' for update");Map<String,Object> m=s.one("select * from shop_member where id=? for update",uid);if(!correct)check(m.get("referrer_id")==null,"推荐来源已确认，不能重复更换");check(ref!=uid&&valid(ref),"推荐人不可用或不能推荐自己");long current=ref;Set<Long> seen=new HashSet<>();while(current>0){check(current!=uid&&seen.add(current),"推荐关系不能形成循环");current=number(s.one("select referrer_id from shop_member where id=?",current).get("referrer_id"));}if(correct)check(reason.trim().length()>=2&&reason.length()<=300,"请填写纠错依据");s.jdbc().update("update shop_member set referrer_id=?,referrer_expires_at=? where id=?",ref,newExpiry(),uid);s.event("referral",uid,"推荐归属从 "+str(m.get("referrer_id"))+" 调整为 "+ref+"；"+reason,who);}
 @Transactional public void companyRelation(long company,long ref,String reason,String who){s.one("select id from shop_company where id=? for update",company);check(valid(ref)&&reason.trim().length()>=2&&reason.length()<=300,"请选择有效推荐人并填写依据");check(s.jdbc().queryForObject("select count(*) from shop_company_member where company_id=? and member_id=?",Long.class,company,ref)==0,"企业成员不能作为本企业推荐人");List<Map<String,Object>> old=s.jdbc().queryForList("select referrer_id from shop_company_referral where company_id=?",company);s.jdbc().update("insert into shop_company_referral(company_id,referrer_id,expires_at) values(?,?,?) on duplicate key update referrer_id=values(referrer_id),expires_at=values(expires_at)",company,ref,newExpiry());s.event("company",company,"推荐归属从 "+(old.isEmpty()?"未绑定":str(old.get(0).get("referrer_id")))+" 调整为 "+ref+"；"+reason,who);}
 public void snapshot(long oid){if("partner".equals(s.one("select business_type from shop_order where id=?",oid).get("business_type"))){s.jdbc().update("insert into shop_distribution_order(order_id,snapshot_json) values(?,?)",oid,"{\"lines\":[],\"reason\":\"专属拿货不计推广佣金\"}");return;}Map<String,Object> o=s.one("select * from shop_order where id=?",oid);long buyer=number(o.get("member_id")),company=number(o.get("company_id")),ref;if(company>0){Map<String,Object> c=s.one("select * from shop_company where id=?",company);inherit(company,number(c.get("certified_member_id")));Map<String,Object> source=s.one("select referrer_id,expires_at from shop_company_referral where company_id=?",company);ref=source.get("expires_at")!=null&&timestamp(source.get("expires_at")).getTime()<=System.currentTimeMillis()?0:number(source.get("referrer_id"));}else ref=effectiveReferrer(buyer);JSONObject config=settings(),snap=new JSONObject();snap.put("lines",new JSONArray());JSONArray lines=snap.getJSONArray("lines");Set<Long> seen=new HashSet<>();JSONObject orderRules=JSON.parseObject(str(o.get("rules_json")));long days=orderRules.getJSONObject("loyalty").getLongValue("commissionDays");for(int depth=1;depth<=2&&ref>0;depth++){if(!seen.add(ref))break;long recipient=ref;ref=effectiveReferrer(ref);if(depth==2&&!config.getBooleanValue("secondEnabled"))break;if(recipient==buyer||!valid(recipient)||company>0&&s.jdbc().queryForObject("select count(*) from shop_company_member where company_id=? and member_id=?",Long.class,company,recipient)>0)continue;s.jdbc().update("insert ignore into shop_distribution_attribution(order_id,member_id,depth) values(?,?,?)",oid,recipient,depth);List<Map<String,Object>> profiles=s.jdbc().queryForList("select tier from shop_distribution_profile where member_id=?",recipient);long tier=profiles.isEmpty()?0:number(profiles.get(0).get("tier"));for(Map<String,Object> i:s.jdbc().queryForList("select * from shop_order_item where order_id=?",oid)){List<Map<String,Object>> rules=s.jdbc().queryForList("select * from shop_distribution_rule where enabled=1 and channel=? and depth=? and product_id in (0,?) and tier in (-1,?) order by (product_id<>0) desc,(tier<>-1) desc limit 1",o.get("channel"),depth,i.get("product_id"),tier);if(rules.isEmpty())continue;Map<String,Object> r=rules.get(0);String basis=str(r.getOrDefault("basis","net"));check(Arrays.asList("net","goods").contains(basis),"佣金规则基数无效，请联系管理员");long net=number(i.get("net_amount")),goods=number(i.get("price"))*number(i.get("quantity")),base="goods".equals(basis)?goods:net,amount="percent".equals(r.get("kind"))?ShopCommerce.portion(base,number(r.get("value")),10000):Math.min(net,number(r.get("value"))*number(i.get("quantity")));if(amount<=0)continue;JSONObject l=new JSONObject();l.put("item",i.get("id"));l.put("member",recipient);l.put("depth",depth);l.put("amount",amount);l.put("basis",basis);l.put("baseAmount",base);l.put("goodsAmount",goods);l.put("netAmount",net);l.put("quantity",i.get("quantity"));l.put("days",days);l.put("rule",r);lines.add(l);}}
 for(Map<String,Object> i:s.jdbc().queryForList("select id,net_amount from shop_order_item where order_id=?",oid)){long sum=0;for(Object obj:lines){JSONObject l=(JSONObject)obj;if(l.getLongValue("item")==number(i.get("id")))sum+=l.getLongValue("amount");}check(sum<=number(i.get("net_amount")),"分销奖励配置超过该商品实付金额，请联系管理员调整");}s.jdbc().update("insert into shop_distribution_order(order_id,snapshot_json) values(?,?)",oid,snap.toJSONString());}
 public boolean paid(long oid){List<Map<String,Object>> rows=s.jdbc().queryForList("select snapshot_json from shop_distribution_order where order_id=?",oid);if(rows.isEmpty())return false;for(Object obj:JSON.parseObject(str(rows.get(0).get("snapshot_json"))).getJSONArray("lines")){JSONObject l=(JSONObject)obj;s.jdbc().update("insert ignore into shop_reward(order_id,item_id,member_id,depth,original_amount,amount,wait_days) values(?,?,?,?,?,?,?)",oid,l.get("item"),l.get("member"),l.get("depth"),l.get("amount"),l.get("amount"),l.get("days"));Map<String,Object> reward=s.one("select id from shop_reward where item_id=? and depth=?",l.get("item"),l.get("depth"));if(s.jdbc().queryForObject("select count(*) from shop_reward_event where reward_id=?",Long.class,reward.get("id"))==0)s.jdbc().update("insert into shop_reward_event(reward_id,member_id,order_id,delta,available_delta,note) values(?,?,?,?,0,'付款生成佣金，按下单快照')",reward.get("id"),l.get("member"),oid,l.get("amount"));}return true;}
 @Transactional public void refresh(long oid){
  Map<String,Object> o=s.one("select * from shop_order where id=? for update",oid);
  List<Map<String,Object>> cases=s.jdbc().queryForList("select * from shop_case where order_id=?",oid),parcels=s.jdbc().queryForList("select * from shop_shipment where order_id=? and received=1 and received_at is not null",oid);
  for(Map<String,Object> r:s.jdbc().queryForList("select r.*,i.quantity from shop_reward r join shop_order_item i on i.id=r.item_id where r.order_id=? for update",oid)){
   long item=number(r.get("item_id")),qty=number(r.get("quantity")),refund=0,unassignedRefund=0,mature=0;boolean blocked=false;java.sql.Timestamp next=null;Map<Long,Long> parcelRefunds=new HashMap<>();
   for(Map<String,Object> c:cases)for(Object obj:JSON.parseArray(str(c.get("items_json")))){
    JSONObject line=JSON.parseObject(JSON.toJSONString(obj));if(line.getLongValue("id")!=item)continue;
    if("refunded".equals(c.get("status"))){
     refund+=line.getLongValue("quantity");long linked=0;JSONArray links=line.getJSONArray("shipmentRefunds");
     if(links!=null)for(Object value:links){JSONObject part=JSON.parseObject(JSON.toJSONString(value));long pid=part.getLongValue("shipmentId"),count=part.getLongValue("quantity");parcelRefunds.put(pid,parcelRefunds.getOrDefault(pid,0L)+count);linked+=count;}
     unassignedRefund+=Math.max(0,line.getLongValue("quantity")-line.getLongValue("unshipped")-linked);
    }else if(!Arrays.asList("completed","rejected").contains(str(c.get("status"))))blocked=true;
   }
   if("refunded".equals(o.get("status")))refund=qty;
   for(Map<String,Object> parcel:parcels){long due=timestamp(parcel.get("received_at")).getTime()+number(r.get("wait_days"))*86400000L;
    for(Object obj:JSON.parseArray(str(parcel.get("items_json")))){JSONObject line=JSON.parseObject(JSON.toJSONString(obj));if(line.getLongValue("id")!=item)continue;long retained=Math.max(0,line.getLongValue("quantity")-parcelRefunds.getOrDefault(number(parcel.get("id")),0L));if(retained==0)continue;if(due<=System.currentTimeMillis())mature+=retained;else if(next==null||due<next.getTime())next=new java.sql.Timestamp(due);}
   }
   // Old cases without parcel attribution keep the conservative deduction. A proven
   // refund from an unreceived parcel must not consume another parcel's earned reward.
   long amount=ShopCommerce.portion(Math.max(0,qty-refund),number(r.get("original_amount")),qty),available=blocked?0:Math.min(amount,ShopCommerce.portion(Math.max(0,Math.min(qty,mature)-unassignedRefund),number(r.get("original_amount")),qty));String reason=blocked?"相关商品售后处理中":amount==0?"退款已扣回":available==amount?"可提现":next==null?"等待实际收货":"等待收货后结算期";long delta=amount-number(r.get("amount")),ad=available-number(r.get("available_amount"));s.jdbc().update("update shop_reward set amount=?,available_amount=?,ready_at=?,reason=? where id=?",amount,available,next,reason,r.get("id"));if(delta!=0||ad!=0)s.jdbc().update("insert into shop_reward_event(reward_id,member_id,order_id,delta,available_delta,note) values(?,?,?,?,?,?)",r.get("id"),r.get("member_id"),oid,delta,ad,reason);
  }
 }
 public long available(long uid){long total=0;for(Map<String,Object> r:s.jdbc().queryForList("select available_amount from shop_reward where member_id=?"+s.verifiedPayment("shop_reward.order_id")+" order by id for update",uid))total+=number(r.get("available_amount"));return total;}
 public boolean frozen(long uid){return s.jdbc().queryForObject("select count(*) from shop_distribution_profile where member_id=? and frozen=1",Long.class,uid)>0;}
 @Transactional public void profile(long uid,JSONObject b,String who){s.one("select id from shop_member where id=? for update",uid);long tier=integer(b.get("tier"),0,2,"请选择等级");String reason=str(b.get("reason")).trim();check(reason.length()>=2&&reason.length()<=500,"请填写调整等级或冻结的原因");s.jdbc().update("insert into shop_distribution_profile(member_id,tier,frozen,reason) values(?,?,?,?) on duplicate key update tier=values(tier),frozen=values(frozen),reason=values(reason)",uid,tier,b.getBooleanValue("frozen"),reason);s.event("distributor",uid,"调整等级/资金冻结："+reason,who);}
 @Transactional public void save(JSONObject b,String who){JSONObject clean=new JSONObject();clean.put("requireApplicationMaterial",b.getBooleanValue("requireApplicationMaterial"));String material=str(b.getOrDefault("applicationMaterialLabel","资格核验资料")).trim();check(material.length()>0&&material.length()<=60,"材料说明为1至60字");clean.put("applicationMaterialLabel",material);clean.put("attributionDays",integer(b.getOrDefault("attributionDays",settings().get("attributionDays")),0,36500,"归属有效天数为0至36500，0表示长期有效"));clean.put("secondEnabled",b.getBooleanValue("secondEnabled"));clean.put("autoTier",b.getBooleanValue("autoTier"));clean.put("silver",integer(b.get("silver"),1,1000000000,"银卡门槛应为正整数分"));clean.put("gold",integer(b.get("gold"),1,1000000000,"金卡门槛应为正整数分"));check(clean.getLongValue("gold")>clean.getLongValue("silver"),"金卡门槛须高于银卡");JSONArray tiers=b.getJSONArray("tiers");check(tiers!=null&&tiers.size()==3,"请填写三个等级名称");for(Object t:tiers)check(!str(t).trim().isEmpty()&&str(t).length()<=20,"等级名称为1至20字");clean.put("tiers",tiers);s.jdbc().update("update shop_config set content=? where config_key='distribution'",clean.toJSONString());s.event("distribution",0,"保存分销设置，新单生效",who);}
 @Transactional public void rule(JSONObject b,String who){String channel=b.getString("channel"),kind=b.getString("kind");check(Arrays.asList("C","B").contains(channel)&&Arrays.asList("percent","fixed").contains(kind),"请选择渠道和奖励方式");long product=integer(b.get("productId"),0,Long.MAX_VALUE,"商品不正确"),tier=integer(b.get("tier"),-1,2,"等级不正确"),depth=integer(b.get("depth"),1,2,"只支持一级或二级"),value=integer(b.get("value"),0,"percent".equals(kind)?5000:100000000,"比例须为0至50%，金额须为非负整数分");if(product>0)s.one("select id from shop_product where id=?",product);s.one("select config_key from shop_config where config_key='distribution' for update");List<Map<String,Object>> existing=s.jdbc().queryForList("select basis from shop_distribution_rule where channel=? and product_id=? and tier=? and depth=? for update",channel,product,tier,depth);String basis=b.containsKey("basis")?str(b.get("basis")):existing.isEmpty()?"net":str(existing.get(0).get("basis"));check(Arrays.asList("net","goods").contains(basis),"请选择商品金额或商品实付分摊额");s.jdbc().update("insert into shop_distribution_rule(channel,product_id,tier,depth,kind,basis,value,enabled) values(?,?,?,?,?,?,?,?) on duplicate key update kind=values(kind),basis=values(basis),value=values(value),enabled=values(enabled)",channel,product,tier,depth,kind,basis,value,b.getBooleanValue("enabled"));s.event("distribution",0,"调整商品佣金，新单生效",who);}
 public long performance(long uid){return s.jdbc().queryForObject("select coalesce(sum(o.amount-o.shipping_amount-o.refunded_amount+o.refunded_shipping_amount),0) from shop_distribution_attribution a join shop_order o on o.id=a.order_id where a.member_id=? and a.depth=1 and o.status='completed' and o.paid_at>=date_sub(now(),interval 365 day)"+s.verifiedPayment("o.id"),Long.class,uid);}
 @Transactional public void updateTier(long uid){Map<String,Object> m=s.one("select id from shop_member where id=? for update",uid);JSONObject c=settings();if(!c.getBooleanValue("autoTier"))return;long amount=performance(uid),tier=amount>=c.getLongValue("gold")?2:amount>=c.getLongValue("silver")?1:0;s.jdbc().update("insert into shop_distribution_profile(member_id,tier) values(?,?) on duplicate key update tier=values(tier)",uid,tier);}
 public Map<String,Object> summary(long uid){Map<String,Object> r=new HashMap<>();r.put("settings",settings());r.put("performance",performance(uid));r.put("profile",s.jdbc().queryForList("select * from shop_distribution_profile where member_id=?",uid));r.put("referrerExpiresAt",s.one("select referrer_expires_at from shop_member where id=?",uid).get("referrer_expires_at"));r.put("referrer",s.one("select referrer_id from shop_member where id=?",uid).get("referrer_id"));r.put("team",s.jdbc().queryForList("select m.id,m.nickname,m.created_at,1 depth,coalesce(p.tier,0) tier from shop_member m left join shop_distribution_profile p on p.member_id=m.id where m.referrer_id=? union all select m.id,m.nickname,m.created_at,2 depth,coalesce(p.tier,0) tier from shop_member m join shop_member parent on parent.id=m.referrer_id left join shop_distribution_profile p on p.member_id=m.id where parent.referrer_id=?",uid,uid));r.put("rewards",s.jdbc().queryForList("select r.*,o.order_no,o.channel,i.name,i.spec from shop_reward r join shop_order o on o.id=r.order_id join shop_order_item i on i.id=r.item_id where r.member_id=?"+s.verifiedPayment("o.id")+" order by r.id desc",uid));r.put("ledger",s.jdbc().queryForList("select * from shop_reward_event where member_id=?"+s.verifiedPayment("shop_reward_event.order_id")+" order by id desc limit 500",uid));r.put("available",s.available(uid));r.put("frozen",frozen(uid));return r;}
}
